import re

def extract_body_literals(topic, sentiment, text_span):
    # Remove filler words and articles
    text_span = re.sub(r'\b(a|an|the)\s*', '', text_span)
    text_span = re.sub(r'\b(very|extremely|quite)\s*', '', text_span)

    # Extract quality, attribute, or characteristic phrases
    literals = []
    for phrase in re.split(r'[.!?]', text_span):
        if phrase:
            words = phrase.split()
            if len(words) > 1 and words[0].lower() == words[-1].lower():
                literal = '_'.join(word.lower() for word in words[:-1])
            else:
                literal = '_'.join(word.lower() for word in words)
            # Filter by sentiment
            if (topic, sentiment) == ('Room', 'Positive'):
                if re.search(r'\b(positive|good)\b', literal):
                    literals.append(literal)
            elif (topic, sentiment) == ('Room', 'Negative'):
                if re.search(r'\b(negative|bad)\b', literal):
                    literals.append(literal)

    return literals

