import re

def extract_body_literals(topic, sentiment, text_span):
    # Remove articles and filler words
    text = re.sub(r'\b(a|an|the)\s*', '', text_span)
    text = re.sub(r'(\s*very\s*|extremely\s*|quite\s*)', '', text)

    # Extract quality, attribute, or characteristic phrases
    if topic == 'Room':
        pattern = r'(good|clean|modern|well\w+|not\s+\w+)room'
    elif topic == 'Staff':
        pattern = r'helpful\s+staff|easy\s+to\s+communicate\s+with'
    elif topic == 'Food':
        pattern = r'tasty\s+food|comfortable\s+(restaurant|restaurant\s+for)'
    elif topic == 'Location':
        pattern = r'(close\w+\s*to|clean)\s+beach'
    elif topic == 'Facility':
        pattern = r'new\s+(apartments|apartment)'
    elif topic == 'Price':
        pattern = r'great\s+value\s+for\s+money'

    body_literals = re.findall(pattern, text)
    if sentiment == 'Positive':
        return [re.sub(r'\b(\w+)\s+', r'\1_', literal) for literal in body_literals]
    elif sentiment == 'Negative':
        return [re.sub(r'\b(\w+)\s+', r'not_\1_', literal) for literal in body_literals]
    else:
        return []

# Test the function
